# This formula is regenerated by the ankra-cli release workflow from
# packaging/homebrew/ankra.rb.tmpl in ankraio/ankra-cli. Manual edits here
# will be overwritten on the next release; change the template instead.
#
# There is deliberately no `version` stanza: `brew audit` fails a tap whose
# declared version it can already scan from the stable URL (redundant_version),
# and every release URL below carries the tag. That is why the URLs interpolate
# nothing - the release workflow substitutes the version into them directly.
class Ankra < Formula
  desc "Command-line interface for the Ankra Kubernetes platform"
  homepage "https://ankra.io"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.43.1/ankra-cli-darwin-arm64"
      sha256 "39e98238da8e8f6042d58172584a311ce5a0c49a020e3c41df43117e6ef023b4"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.43.1/ankra-cli-darwin-amd64"
      sha256 "cecd297b45c759439c3b39721f200efdf91598561328a603ac0bc5630a94b4f2"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.43.1/ankra-cli-linux-arm64"
      sha256 "739c963f2be7a70b08958748d3157fff870bd958ad7adc314743efcc9ebff5aa"
    end
    on_intel do
